":"object"},"schema_hash":"277129169637fc5fd07a81f4b0d7782a1a82845deda8ee64041553c9677860a0","side_effect":"none","tool_group":"artifact"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel","user"],"authorization_requirement":"explicit_intent","cancel_semantics":"best_effort","canonical_name":"file_analyze","capability_requirements":["artifact.materialize"],"description":"读取数据文件（.xlsx/.xls/.csv/.tsv）的完整结构，自动转为 Parquet 缓存。\n自动处理多级表头、合并单元格、表头偏移、特殊行检测，比手动 openpyxl 读取更准确。\n\nWhen to use:\n- attachments 中 status=raw 的 .xlsx/.xls/.csv/.tsv 文件首次治理\n- 需要 Parquet 路径供 code_execute 中 duckdb/pandas 查询\n\nWhen NOT to use:\n- 已 status=analyzed 的文件 — 直接用 <parquet> 字段 pd.read_parquet，禁止重复治理\n- 图片文件（.png/.jpg/.jpeg/.gif/.webp/.bmp）— 已通过视觉通道注入\n- PDF/Word/PPT/文本文件 — 用 code_execute + 对应库读取\n\nReturns: 列名、数据类型、行数、样本数据、Parquet 缓存相对路径。\n支持扩展名: .xlsx .xls .csv .tsv（其他不支持）","executor_revision":1,"executor_type":"runtime_artifact_job:file_analyze","provider_schema":{"additionalProperties":false,"properties":{"file_id":{"type":"string"},"path":{"type":"string"},"sheet":{"type":"string"}},"required":["file_id"],"type":"object"},"provider_schema_hash":"6457ba7ca6465e93f776a0566e1a1ffad2e848831559e173d96ca6d777ab71d1","reconcile_semantics":"executor_defined","result_schema_revision":1,"retry_semantics":"reconcile_only","safety_level":"confirm","schema":{"additionalProperties":false,"properties":{"file_id":{"type":"string"},"path":{"type":"string"},"sheet":{"type":"string"}},"required":["file_id"],"type":"object"},"schema_hash":"6457ba7ca6465e93f776a0566e1a1ffad2e848831559e173d96ca6d777ab71d1","side_effect":"none","tool_group":"artifact"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel","user"],"authorization_requirement":"none","cancel_semantics":"unsupported","canonical_name":"get_conversation_context","capability_requirements":["runtime.conversation.read"],"description":"获取当前对话的最近消息记录","executor_revision":1,"executor_type":"runtime_read:get_conversation_context","provider_schema":{"additionalProperties":false,"properties":{"limit":{"type":"integer"}},"required":[],"type":"object"},"provider_schema_hash":"16986a66e5924b0c9c609019112350948a47c0a6f9247b9419330aded057df8c","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"limit":{"type":"integer"}},"required":[],"type":"object"},"schema_hash":"16986a66e5924b0c9c609019112350948a47c0a6f9247b9419330aded057df8c","side_effect":"none","tool_group":"runtime"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel"],"authorization_requirement":"none","cancel_semantics":"unsupported","canonical_name":"local_compare_stats","capability_requirements":["erp.local.compare_stats"],"description":"时间维度对比统计（同比/环比/任意区间对比）。毫秒级响应。由后端确定地计算对比基线（含中文星期/相对时间标签），返回结构化双时间块 + 数据对比。⚠ 涉及「对比/同比/环比/比上周/比上月/比去年」的查询必须用本工具，禁止调用 local_data 两次再让模型口述对比。适合：今天 vs 昨天、本周 vs 上周、本月 vs 上月同期、订单同比去年同期等。相关工具：对比后需要明细数据用 local_data(mode=export)；单商品对比趋势用 local_product_stats。","executor_revision":1,"executor_type":"runtime_read:local_compare_stats","provider_schema":{"additionalProperties":false,"properties":{"compare_kind":{"type":"string"},"current_period":{"type":"string"},"doc_type":{"type":"string"},"platform":{"type":"string"},"shop_name":{"type":"string"},"supplier_name":{"type":"string"},"warehouse_name":{"type":"string"}},"required":["doc_type","compare_kind","current_period"],"type":"object"},"provider_schema_hash":"de6b05a5e475786ddbdc06295bf7175f7aff9f9f994319806f4beb7ae93a97f1","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"compare_kind":{"type":"string"},"current_period":{"type":"string"},"doc_type":{"type":"string"},"platform":{"type":"string"},"shop_name":{"type":"string"},"supplier_name":{"type":"string"},"warehouse_name":{"type":"string"}},"required":["doc_type","compare_kind","current_period"],"type":"object"},"schema_hash":"de6b05a5e475786ddbdc06295bf7175f7aff9f9f994319806f4beb7ae93a97f1","side_effect":"none","tool_group":"erp_local"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel","user"],"authorization_requirement":"explicit_intent","cancel_semantics":"best_effort","canonical_name":"local_data","capability_requirements":["artifact.materialize"],"description":"本地数据库统一查询工具。支持查询/统计/导出 ERP 全部业务表数据。\n除单据表外还支持：库存(stock)、商品(product)、SKU(sku)、日统计(daily_stats)、平台映射(platform_map)、批次库存(batch_stock)、订单日志(order_log)、售后日志(aftersale_log)。\n用 filters 数组指定过滤条件，任意字段组合均可。\n\n常用字段：\n- order_status/doc_status: 状态(WAIT_AUDIT/WAIT_SEND_GOODS/SELLER_SEND_GOODS/FINISHED/CLOSED)\n- consign_time: 发货时间  |  pay_time: 付款时间  |  doc_created_at: 创建时间\n- shop_name: 店铺名  |  platform: 平台(tb/jd/pdd/fxg/kuaishou/xhs/1688)\n- outer_id: 商品主编码  |  sku_outer_id: SKU编码  |  item_name: 商品名称\n- order_no: 平台订单号  |  express_no: 快递单号\n- supplier_name: 供应商  |  warehouse_name: 仓库\n- amount: 金额  |  pay_amount: 实付金额  |  quantity: 数量\n- cost: 成本  |  gross_profit: 毛利润  |  price: 单价\n- post_fee: 运费  |  discount_fee: 优惠金额  |  refund_money: 退款金额\n- is_scalping: 是否刷单/空包(0=正常,1=刷单)  |  is_exception: 是否异常订单(0/1)\n- is_refund: 是否退款(0/1)  |  is_cancel: 是否取消(0/1)\n- aftersale_type: 售后类型(0~9)  |  refund_status: 退款状态  |  text_reason: 售后原因\n- buyer_nick: 买家昵称  |  status_name: 状态中文名\n\nop: eq(等于) ne(不等于) gt(大于) gte(>=) lt(<) lte(<=) in(在列表中) like(模糊) is_null(是否空) between(区间)\n\n示例1：4月14日已发货订单列表\n  doc_type=order, mode=detail, filters=[\n    {\"field\":\"order_status\",\"op\":\"eq\",\"value\":\"SELLER_SEND_GOODS\"},\n    {\"field\":\"consign_time\",\"op\":\"gte\",\"value\":\"2026-04-14 00:00:00\"},\n    {\"field\":\"consign_time\",\"op\":\"lt\",\"value\":\"2026-04-15 00:00:00\"}]\n\n示例2：淘宝金额>500订单按店铺统计\n  doc_type=order, mode=summary, filters=[\n    {\"field\":\"platform\",\"op\":\"eq\",\"value\":\"tb\"},\n    {\"field\":\"amount\",\"op\":\"gt\",\"value\":500}],\n  group_by=[\"shop_name\"]\n\n示例3：导出3月拼多多发货订单\n  doc_type=order, mode=export, filters=[...],\n  fields=[\"order_no\",\"amount\",\"consign_time\"]","executor_revision":1,"executor_type":"runtime_artifact_job:local_data","provider_schema":{"additionalProperties":false,"properties":{"alert_type":{"type":"string"},"compare_range":{"type":"string"},"doc_type":{"enum":["order","purchase","aftersale","receipt","shelf","purchase_return","stock","daily_stats"],"type":"string"},"extra_fields":{"items":{"type":"string"},"type":"array"},"filters":{"type":"array"},"group_by":{"items":{"type":"string"},"type":"array"},"limit":{"maximum":200,"minimum":1,"type":"integer"},"metrics":{"items":{"type":"string"},"type":"array"},"mode":{"type":"string"},"query_type":{"enum":["trend","compare","cross","distribution"],"type":"string"},"sort_by":{"type":"string"},"sort_dir":{"enum":["asc","desc"],"type":"string"},"time_granularity":{"type":"string"},"time_type":{"type":"string"}},"required":["doc_type","query_type"],"type":"object"},"provider_schema_hash":"506b722228098ee1ce7d3e07244f186ccdf3897278e7e1d1e7b8ed6cf2aa8303","reconcile_semantics":"executor_defined","result_schema_revision":1,"retry_semantics":"reconcile_only","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"alert_type":{"type":"string"},"compare_range":{"type":"string"},"doc_type":{"enum":["order","purchase","aftersale","receipt","shelf","purchase_return","stock","daily_stats"],"type":"string"},"extra_fields":{"items":{"type":"string"},"type":"array"},"filters":{"type":"array"},"group_by":{"items":{"type":"string"},"type":"array"},"limit":{"maximum":200,"minimum":1,"type":"integer"},"metrics":{"items":{"type":"string"},"type":"array"},"mode":{"type":"string"},"query_type":{"enum":["trend","compare","cross","distribution"],"type":"string"},"sort_by":{"type":"string"},"sort_dir":{"enum":["asc","desc"],"type":"string"},"time_granularity":{"type":"string"},"time_type":{"type":"string"}},"required"