ice: 单价\n- post_fee: 运费  |  discount_fee: 优惠金额  |  refund_money: 退款金额\n- is_scalping: 是否刷单/空包(0=正常,1=刷单)  |  is_exception: 是否异常订单(0/1)\n- is_refund: 是否退款(0/1)  |  is_cancel: 是否取消(0/1)\n- aftersale_type: 售后类型(0~9)  |  refund_status: 退款状态  |  text_reason: 售后原因\n- buyer_nick: 买家昵称  |  status_name: 状态中文名\n\nop: eq(等于) ne(不等于) gt(大于) gte(>=) lt(<) lte(<=) in(在列表中) like(模糊) is_null(是否空) between(区间)\n\n示例1：4月14日已发货订单列表\n  doc_type=order, mode=detail, filters=[\n    {\"field\":\"order_status\",\"op\":\"eq\",\"value\":\"SELLER_SEND_GOODS\"},\n    {\"field\":\"consign_time\",\"op\":\"gte\",\"value\":\"2026-04-14 00:00:00\"},\n    {\"field\":\"consign_time\",\"op\":\"lt\",\"value\":\"2026-04-15 00:00:00\"}]\n\n示例2：淘宝金额>500订单按店铺统计\n  doc_type=order, mode=summary, filters=[\n    {\"field\":\"platform\",\"op\":\"eq\",\"value\":\"tb\"},\n    {\"field\":\"amount\",\"op\":\"gt\",\"value\":500}],\n  group_by=[\"shop_name\"]\n\n示例3：导出3月拼多多发货订单\n  doc_type=order, mode=export, filters=[...],\n  fields=[\"order_no\",\"amount\",\"consign_time\"]","executor_revision":1,"executor_type":"runtime_artifact_job:local_data","provider_schema":{"additionalProperties":false,"properties":{"alert_type":{"type":"string"},"compare_range":{"type":"string"},"doc_type":{"enum":["order","purchase","aftersale","receipt","shelf","purchase_return","stock","daily_stats"],"type":"string"},"extra_fields":{"items":{"type":"string"},"type":"array"},"filters":{"type":"array"},"group_by":{"items":{"type":"string"},"type":"array"},"limit":{"maximum":200,"minimum":1,"type":"integer"},"metrics":{"items":{"type":"string"},"type":"array"},"mode":{"type":"string"},"query_type":{"enum":["trend","compare","cross","distribution"],"type":"string"},"sort_by":{"type":"string"},"sort_dir":{"enum":["asc","desc"],"type":"string"},"time_granularity":{"type":"string"},"time_type":{"type":"string"}},"required":["doc_type","query_type"],"type":"object"},"provider_schema_hash":"506b722228098ee1ce7d3e07244f186ccdf3897278e7e1d1e7b8ed6cf2